def round_num_to_digit(num: int, digit: int) -> float:
    """ Given a floating point number and a digit (pos or neg value), round
    the number to the given digit place.

    >>> round_num_to_digit(72.723, 3)
    72.723
    >>> round_num_to_digit(23.145, 0)
    20
    """
    if abs(round(num) - num) >= 0.5 and digit > 0:
        return int(round(num * 10) / 10)
    elif abs(round(num) - num) >= 0.5 and digit <= 0:
        return 0
    elif abs(round(num) - num) < 0.5 and digit > 0:
        return int(round(num) + 0.5)
    else:
        return 0

