def normalize_coordinates(planet_x: float, planet_y: float) -> Tuple[float, float]:
    """ Normalize coordinates based on Planet size.

    In the coordinates system, the planets have different sizes,
    so they can't be centered in the same place.

    Return tuple with new coordinates.

    >>> normalize_coordinates(2.0, 1.5)
    (2.0, 1.5)
    """
    if planet_x > 0.8:
        return planet_x, planet_y
    elif planet_x < 0.8:
        return 2.0 - planet_x, planet_y
    else:
        return 0.0, planet_y


