def first_not_repeating_character(s: str) -> str:
    """ Given a string, find the first non-repeating character in it and return it's index.
    If it doesn't exist, return -1. Try to do it in O(s) time and O(1) space.
    >>> first_not_repeating_character('abacabad')
    4
    >>> first_not_repeating_character('abacabaabacaba')
    4
    >>> first_not_repeating_character('')
    -1
    """
    chars = {}

    for i in range(len(s)):
        if s[i] not in chars:
            chars[s[i]] = 1
        else:
            chars[s[i]] += 1

    for i in range(len(s)):
        if chars[s[i]] == 1:
            return i
    return -1


